estilos.css_firma:
/* 147 · paleta y fuentes (lienzo ronda 8, .m147) */
.m147 .tel-pantalla{--fondo:#f5efe3;--hoja:#ece4d4;--carta:#fffcf6;--linea:#dcd2c0;--linea-2:#b8ac96;
  --tinta:#1b1e4b;--tinta-1:#34386b;--tinta-2:#4d5180;--tinta-3:#5c5f88;--indigo:#1b1e4b;--indigo-2:#2a2e66;--marfil:#f5efe3;
  --coral:#ff6a4d;--coral-suave:#ffd9cf;--sombra:rgba(27,30,75,.28);
  --f-tit:"Anton","Bebas Neue","Arial Narrow",sans-serif;--f-cond:"Barlow Condensed","Arial Narrow",sans-serif;--f-txt:"Archivo",system-ui,sans-serif;
  background:var(--fondo);color:var(--tinta);font-family:var(--f-txt)}
.m147 .tit{font-family:var(--f-tit);font-weight:400;text-transform:uppercase;letter-spacing:.2px;line-height:.95}
.m147 .kicker{font-family:var(--f-txt);font-stretch:112%;font-weight:700;font-size:12px;letter-spacing:2px;text-transform:uppercase;color:var(--tinta-2)}
/* duotono índigo (sombras) -> marfil (luces) */
.m147 .foto{position:absolute;inset:0;overflow:hidden;background:var(--indigo);isolation:isolate}
.m147 .foto img{filter:grayscale(1) contrast(1.25) brightness(1.04);mix-blend-mode:screen}
.m147 .foto::before{content:"";position:absolute;inset:0;z-index:1;background:var(--marfil);mix-blend-mode:multiply}
.m147 .zoom img{animation:m147-zoom 24s var(--curva) infinite alternate;transform-origin:60% 40%}
/* la línea móvil "Último" */
.m147 .tick{display:flex;height:38px;background:var(--coral);border-top:1px solid var(--indigo);border-bottom:1px solid var(--indigo);overflow:hidden}
.m147 .tick-l{display:flex;align-items:center;gap:7px;padding:0 12px;background:var(--indigo);color:var(--marfil);font-family:var(--f-cond);font-weight:800;font-size:14px;letter-spacing:1.6px;text-transform:uppercase}
.m147 .tick-v{flex:1;overflow:hidden;mask-image:linear-gradient(90deg,transparent 0,#000 18px,#000 calc(100% - 26px),transparent)}
.m147 .tick-pista{display:flex;gap:34px;white-space:nowrap;animation:m147-corre 30s linear infinite;font-family:var(--f-cond);font-weight:600;font-size:16.5px;color:var(--indigo)}
.m147 .tick-pista span::before{content:"";width:6px;height:6px;background:var(--indigo);transform:rotate(45deg)}
/* zócalo: banda vertical + texto */
.m147 .zoc-b{display:flex;align-items:center;padding:0 11px;background:var(--indigo);color:var(--marfil);font-family:var(--f-cond);font-weight:700;font-size:12.5px;letter-spacing:1.5px;text-transform:uppercase;writing-mode:vertical-rl;transform:rotate(180deg)}
.m147 .zoc-t{flex:1;background:var(--carta);padding:14px 16px 16px;box-shadow:0 0 0 1px var(--linea),0 16px 30px -16px var(--sombra)}
/* saludo con resaltador coral detrás del nombre */
.m147 .hola{font-size:54px;line-height:.9}
.m147 .hola b{font-weight:400;padding:0 .05em;background:linear-gradient(180deg,transparent 56%,var(--coral) 56%,var(--coral) 90%,transparent 90%);box-decoration-break:clone}
/* tablero de accesos: celdas separadas por filetes de 1px */
.m147 .tablero{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--linea)}
.m147 .celda{display:flex;flex-direction:column;gap:12px;min-height:118px;padding:16px 14px 14px;background:var(--fondo)}
.m147 .celda b{font-family:var(--f-tit);font-weight:400;font-size:21px;line-height:1;text-transform:uppercase;margin-top:auto}
.m147 .sec-tit{display:flex;align-items:flex-end;justify-content:space-between;padding-bottom:10px;border-bottom:2px solid var(--tinta)}
.m147 .btn{min-height:48px;padding:0 22px;border:0;border-radius:2px;font-stretch:108%;font-weight:700;font-size:14px;letter-spacing:1.2px;text-transform:uppercase}
.m147 .btn-uno{background:var(--coral);color:var(--indigo);box-shadow:inset 0 -2px 0 rgba(27,30,75,.22)}
.m147 .pasos li.actual{color:var(--tinta);border-top:4px solid var(--coral);padding-top:5px}
.m147 .pestanas a.on::after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:3px;background:var(--coral)}
.m147 th{font-stretch:108%;font-size:11px;font-weight:700;letter-spacing:1.4px;text-transform:uppercase;border-bottom:1px solid var(--tinta)}
/* tablero de la app (static/temas/noticiero-tablero.css) */
html[data-tema="noticiero"] .v2-tablero{background:var(--nt-carta);border-radius:0;border-top:4px solid var(--nt-tinta);box-shadow:0 0 0 1px var(--nt-linea),0 22px 40px -30px var(--nt-sombra)}
html[data-tema="noticiero"] .v2-hero{background:transparent;border-radius:0;padding:4px 18px 6px;border-left:1px solid var(--nt-linea)}
html[data-tema="noticiero"] .v2-hero .val{font-family:var(--nt-f-tit);font-weight:400;font-size:40px;font-variant-numeric:tabular-nums}
html[data-tema="noticiero"] .v2-hero.grande .val{font-size:68px;line-height:1}

/* 151 · paleta (lienzo ronda 8, .m151) */
.m151 .tel-pantalla{--fondo:#0c0d10;--hoja:#141619;--hoja-2:#181a1e;--campo:#08090b;--linea:#262a31;--linea-2:#3a3f48;
  --blanco:#f4f5f7;--gris-1:#cfd2d8;--gris-2:#a5aab4;--gris-3:#8b919c;--lima:#C6FF3D;--tinta-lima:#0c0d10;--claro:#d4d7dc;
  --f-tit:"Anton","Bebas Neue","Arial Narrow",sans-serif;--f-cond:"Barlow Condensed","Arial Narrow",sans-serif;--f-txt:"Archivo",system-ui,sans-serif;
  background:var(--fondo);color:var(--blanco);font-family:var(--f-txt)}
/* fotos en blanco y negro duro, sin tinte */
.m151 .foto{position:absolute;inset:0;overflow:hidden;background:#050607}
.m151 .foto img{filter:grayscale(1) contrast(1.4) brightness(.92);mix-blend-mode:luminosity;opacity:.94}
.m151 .foto::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(8,9,11,.62) 0%,rgba(8,9,11,0) 24%,rgba(8,9,11,.1) 48%,var(--fondo) 97%)}
/* la línea móvil: rótulo lima, pista blanca sobre casi negro */
.m151 .tick{display:flex;height:38px;background:#050607;border-top:1px solid var(--linea);border-bottom:1px solid var(--linea)}
.m151 .tick-l{display:flex;align-items:center;gap:7px;padding:0 12px;background:var(--lima);color:var(--tinta-lima);font-family:var(--f-cond);font-weight:800;font-size:14px;letter-spacing:1.6px;text-transform:uppercase}
.m151 .tick-pista span::before{content:"";width:6px;height:6px;background:var(--lima);transform:rotate(45deg)}
/* el resaltador: lima DETRÁS de tinta negra */
.m151 .resalta{color:var(--tinta-lima);background-image:linear-gradient(var(--lima),var(--lima));background-repeat:no-repeat;padding:0 .12em;box-decoration-break:clone}
.m151 .hola .resalta{animation:m151-resalta .8s .5s var(--curva) both}
/* zócalo: banda gris clara + texto sobre blanco */
.m151 .zoc-b{padding:0 11px;background:var(--claro);color:#0c0d10;font-family:var(--f-cond);font-weight:700;font-size:12.5px;letter-spacing:1.5px;text-transform:uppercase;writing-mode:vertical-rl;transform:rotate(180deg)}
.m151 .zoc-t{flex:1;background:var(--blanco);color:#111318;padding:14px 16px 16px;box-shadow:0 14px 30px -14px rgba(0,0,0,.7)}
.m151 .btn-uno{background:var(--lima);color:var(--tinta-lima)}
.m151 .btn-uno:hover{filter:brightness(1.06);box-shadow:0 0 0 4px rgba(198,255,61,.16)}
.m151 .tablero{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--linea)}
.m151 .celda.uno-c{box-shadow:inset 0 2px 0 var(--blanco)}
/* ronda 9 (pantallas reales, .p151e): el negro es cromo; listados sobre HOJA clara con lomo */
.p151e .pc-pantalla{--papel:#f4f5f7;--papel-2:#eaecef;--tinta:#111318;--tinta-2:#30353d;--tinta-3:#525863;--raya:#d3d7dd}
.p151e .conlat{display:grid;grid-template-columns:208px minmax(0,1fr)}
.p151e .lat a{min-height:36px;padding:0 14px 0 18px;font-family:var(--f-cond);font-weight:600;font-size:14.5px;letter-spacing:.8px;text-transform:uppercase}
.p151e .lat a.on{color:#0c0d10;background:var(--blanco);font-weight:700}
.p151e .banda h1{font-size:44px;line-height:.95}
.p151e .hoja{display:grid;grid-template-columns:30px minmax(0,1fr);margin:0 32px;background:var(--papel);color:var(--tinta);box-shadow:0 22px 44px -26px rgba(0,0,0,.9)}
.p151e .lomo{display:flex;align-items:center;justify-content:center;background:var(--claro);color:#0c0d10;font-family:var(--f-cond);font-weight:700;font-size:12.5px;letter-spacing:1.6px;text-transform:uppercase;writing-mode:vertical-rl;transform:rotate(180deg)}
.p151e .hoja .sec-c{padding-bottom:10px;border-bottom:2px solid var(--tinta);margin-bottom:14px}
.p151e .subt a.on{background:var(--blanco);color:#0c0d10;box-shadow:none}

/* 158 · paleta (lienzo ronda 8, .m158) */
.m158 .tel-pantalla{--negro:#171a20;--tinta:#171a20;--gris:#393c41;--gris2:#54575c;--papel:#f1f2f4;--hoja:#ffffff;
  --claro:#e7e9ec;--claro2:#e2e4e7;--linea:#dcdee2;--linea2:#c7cacf;--fluor:#e6ff1f;--fluor-h:#d8f000;--fluor-filo:rgba(23,26,32,.16);
  --curva:cubic-bezier(.22,.61,.36,1);font-family:"Manrope","Hanken Grotesk",system-ui,sans-serif;color:var(--tinta);background:var(--papel);letter-spacing:.005em}
.m158 .f-kick{font-size:11.5px;font-weight:500;letter-spacing:.22em;text-transform:uppercase;color:var(--gris2)}
.m158 .f-pill{height:42px;padding:0 26px;border-radius:999px;font-size:14px;font-weight:500;letter-spacing:.02em}
.m158 .f-pill.osc{background:var(--fluor);color:var(--negro);font-weight:600;box-shadow:inset 0 0 0 1px var(--fluor-filo),0 6px 16px -10px rgba(110,125,0,.55)}
.m158 .f-opc label{height:40px;padding:0 18px;border-radius:999px;border:1px solid var(--linea2);background:#fff;font-size:13.5px;font-weight:500}
.m158 .f-opc label:has(input:checked){border-color:var(--negro);background:var(--fluor);color:var(--negro);box-shadow:inset 0 0 0 1px var(--negro)}
.m158 .f-seg{display:inline-flex;padding:3px;border-radius:999px;background:var(--claro)}
.m158 .f-seg label:has(input:checked){background:var(--fluor);color:var(--negro);box-shadow:0 1px 2px rgba(0,0,0,.08),inset 0 0 0 1px var(--fluor-filo)}
.m158 .f-in{height:44px;border:1px solid transparent;border-radius:4px;background:var(--claro);padding:0 14px}
.m158 .f-in:focus{background:#fff;border-color:var(--negro);outline:none}
/* resaltador: flúor detrás de texto negro */
.m158 .f-resalta{padding:0 .14em;color:var(--negro);background-image:linear-gradient(transparent 52%,var(--fluor) 52%,var(--fluor) 94%,transparent 94%);background-repeat:no-repeat;box-decoration-break:clone}
/* portada serena: foto gris lavada con velo de papel */
.m158 .f-hero{position:relative;height:560px;overflow:hidden;background:#dcdcdc;display:flex;flex-direction:column}
.m158 .f-media img{filter:grayscale(1) brightness(1.08) contrast(.92)}
.m158 .f-hero::after{background:linear-gradient(180deg,rgba(241,242,244,.95) 0%,rgba(241,242,244,.86) 30%,rgba(241,242,244,.15) 50%,rgba(241,242,244,0) 60%,rgba(241,242,244,.6) 78%,rgba(241,242,244,.95) 92%,var(--papel) 100%)}
.m158 .f-hero-txt h1{font-size:36px;font-weight:500;letter-spacing:-.005em;line-height:1.05}
.m158 .f-sec-cab h2{font-size:12.5px;font-weight:600;letter-spacing:.2em;text-transform:uppercase}
/* evaluador: el recibo como objeto en un escenario */
.m158 .f-escena{height:236px;background:linear-gradient(180deg,var(--papel) 0%,var(--claro) 55%,#dfe1e5 100%);display:grid;place-items:center;perspective:900px}
.m158 .f-papel{width:222px;background:#fff;border-radius:3px;padding:14px;box-shadow:0 1px 0 rgba(0,0,0,.04),0 18px 30px -16px rgba(0,0,0,.28);transform:rotateX(14deg) rotateZ(-3deg) translateY(-6px)}
.m158 .f-ficha{display:grid;grid-template-columns:1fr 1fr 1fr;border-top:1px solid var(--linea);border-bottom:1px solid var(--linea)}
.m158 .f-ficha b{font-size:18px;font-weight:500;font-variant-numeric:tabular-nums}
/* noticias: el configurador */
.m158 .f-conf{display:grid;grid-template-columns:1fr 480px}
.m158 .f-esc{background:linear-gradient(180deg,var(--papel) 0%,var(--claro) 46%,#dcdfe3 100%);display:flex;flex-direction:column;align-items:center;padding:40px}
.m158 .f-movil{width:292px;border-radius:38px;background:var(--negro);padding:10px;box-shadow:0 40px 60px -34px rgba(0,0,0,.5)}
.m158 .f-cierre{position:sticky;bottom:0;padding:20px 44px 28px;background:rgba(255,255,255,.94);backdrop-filter:blur(12px);border-top:1px solid var(--linea)}
/* ronda 9 (panel real, .p158e): riel lateral, la activa en negro con filete flúor */
.p158e .lat a[aria-current="page"]{background:var(--negro);color:#fff;font-weight:600;box-shadow:inset 3px 0 0 var(--fluor)}
.p158e .hero-ps{margin:-96px 40px 0;display:grid;grid-template-columns:1fr 220px;gap:30px;padding:30px 36px;border-radius:10px;background:var(--hoja);box-shadow:0 30px 60px -36px rgba(0,0,0,.45),0 0 0 1px var(--linea)}

/* 162 · paleta (lienzo ronda 8, .m162) */
.m162 .tel-pantalla{--negro:#171a20;--tinta:#171a20;--gris:#393c41;--gris2:#5c5e62;--claro:#f4f4f4;--linea:#e3e4e5;--linea2:#d0d1d2;
  --azul:#0b2f4f;--azul2:#0d4a6e;--turq:#0a7f8c;--turq-h:#086e79;--turq-osc:#08636d;--lag:#13a3a0;--agua:#8de6d4;--agua-f:#dff6f1;--agua-f2:#eefaf7;--azgris:#3d5a6c;--fluor:#46f0d2;
  --curva:cubic-bezier(.22,.61,.36,1);font-family:"Manrope","Hanken Grotesk",system-ui,sans-serif;color:var(--tinta);background:#fff}
/* el filete turquesa de las pantallas livianas */
.m162 .f-filete{box-shadow:inset 0 3px 0 var(--turq)}
.m162 .f-pill{height:42px;padding:0 26px;border-radius:999px;font-size:14px;font-weight:500;letter-spacing:.02em}
.m162 .f-pill.osc{background:var(--turq);color:#fff}
/* 1 · la laguna: degradé + foto por luminosidad + velo de varias paradas */
.m162 .tel-pantalla.f-laguna{--tinta:var(--azul);color:var(--azul);background:linear-gradient(180deg,var(--agua-f) 0,var(--agua-f) 600px,#e6f8f3 60%,var(--agua-f2) 100%)}
.m162 .f-hero{position:relative;height:560px;overflow:hidden;background:var(--azul);display:flex;flex-direction:column}
.m162 .f-media{position:absolute;inset:0;background:linear-gradient(180deg,var(--azul2) 0%,var(--turq) 42%,var(--lag) 62%,var(--agua) 100%);animation:m162-respira 28s ease-in-out infinite alternate}
.m162 .f-media img{filter:grayscale(1) contrast(1.08) brightness(1.04);mix-blend-mode:luminosity;opacity:.9}
.m162 .f-hero::after{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(180deg,rgba(11,47,79,.97) 0%,rgba(11,47,79,.9) 30%,rgba(10,90,120,.42) 46%,rgba(19,163,160,.12) 58%,rgba(141,230,212,.22) 66%,rgba(176,238,226,.86) 80%,rgba(223,246,241,.97) 90%,var(--agua-f) 100%)}
.m162 .f-hero-txt{text-align:center;padding:30px 28px 0}
.m162 .f-hero-txt .f-kick{color:var(--fluor)}
.m162 .f-hero-txt h1{font-size:36px;font-weight:500;letter-spacing:-.005em;line-height:1.05;color:#fff}
.m162 .f-hero-acc .f-pill{width:100%;max-width:300px;background:var(--fluor);color:var(--azul);font-weight:600;box-shadow:0 10px 24px -12px rgba(11,47,79,.55),0 0 0 1px rgba(11,47,79,.12)}
.m162 .f-mini{height:30px;padding:0 13px;border-radius:999px;background:rgba(255,255,255,.7);backdrop-filter:blur(10px)}
.m162 .f-laguna .f-hola h2 b{background:linear-gradient(180deg,transparent 60%,rgba(70,240,210,.8) 60%,rgba(70,240,210,.8) 92%,transparent 92%)}
.m162 .f-laguna .f-sec-cab h2{font-size:12.5px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;padding-bottom:4px;box-shadow:inset 0 -2px 0 var(--lag)}
.m162 .f-lamina{height:320px;border-radius:6px;overflow:hidden;background:linear-gradient(180deg,var(--agua) 0%,var(--lag) 45%,var(--azul2) 100%)}
.m162 .f-lamina img{filter:grayscale(1) contrast(1.05);mix-blend-mode:luminosity}
.m162 .f-laguna .f-pie{margin-top:42px;padding:26px 24px 32px;background:var(--azul);color:#d3f2f0}
/* lo liviano: paso activo que se llena en turquesa */
.m162 .f-riel li::before{content:"";display:block;height:2px;border-radius:2px;margin-bottom:8px;background:var(--linea)}
.m162 .f-riel li.ahora::after{content:"";position:absolute;left:0;right:0;top:0;height:2px;background:var(--turq);transform-origin:left;animation:m162-llena 1.1s .2s var(--curva) both}
.m162 .f-paso.ahora .f-paso-cab .n{background:var(--turq);border-color:var(--turq);color:#fff}
.m162 .f-t th{font-size:11px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--gris2);border-bottom:1px solid var(--linea2)}
/* tablero en la app (static/temas/laguna-tablero.css) */
html[data-tema="laguna"] .marca-barra{height:88px;background:#fff;box-shadow:inset 0 3px 0 var(--lg-turq);border-bottom:1px solid var(--lg-linea)}
html[data-tema="laguna"] .v2-tablero{background:var(--lg-agua-f2);border-radius:14px;padding:18px 20px 20px;box-shadow:0 0 0 1px color-mix(in oklab,var(--lg-lag) 22%,var(--lg-linea))}
html[data-tema="laguna"] .v2-hero{background:#fff;box-shadow:0 0 0 1px var(--lg-linea);border-radius:12px;padding:16px}
html[data-tema="laguna"] .v2-chip.act{background:var(--destacado);color:#fff;font-weight:700}
html[data-tema="laguna"] .tab-btn.activa{background:var(--lg-azul);color:#fff;font-weight:700;border-radius:8px}
